import{D as ae}from"./DataBadge-Di0oYv38.js";import{_ as G,u as ue,I as oe,c as D,s as pe,k as ve,d as he,q as z,e as H,f as ge,a as fe}from"./index-B_qR7tiI.js";import{o as s,c as a,A as Q,e,F as $,n as Y,j as A,K as te,w as ye,r as ie,i as se,f as M,g as V,t,a as R,T as J,h as C,x as O,l as me,E as xe,G as ke,m as be,p as S,q as E,d as _e,k}from"./vue-CDcswcN0.js";import{m as ce,e as re}from"./index-DcKlO9-6.js";import"./gsap-SFc2wnMY.js";import"./B0005-CFtpngFu.js";const we={class:"rf-eyes"},$e=["cy","r"],Se=["cy","r"],Ce={key:0,class:"rf-mouth rf-mouth-fill",d:"M26.5 33 Q32 39.5 37.5 33 Z"},Le={key:1,class:"rf-mouth",d:"M26.5 35.4 Q32 32.7 37.5 35.4"},Ae={key:2,class:"rf-mouth",cx:"32",cy:"34.2",r:"1.9"},qe={key:3,class:"rf-mouth",d:"M26.5 33.4 Q32 37.4 37.5 33.4"},Ee={__name:"RobotFace",props:{mood:{type:String,default:"idle"},size:{type:Number,default:40}},setup(c){return(n,i)=>(s(),a("svg",{class:A(["robot-face","mood-"+c.mood]),style:Y({width:c.size+"px",height:c.size+"px"}),viewBox:"0 0 64 64","aria-hidden":"true"},[i[2]||(i[2]=Q('<line class="rf-antenna" x1="32" y1="13.5" x2="32" y2="7.4" data-v-477548e5></line><circle class="rf-bulb" cx="32" cy="4.6" r="3.2" data-v-477548e5></circle><rect class="rf-ear" x="5" y="26" width="4.6" height="12" rx="2.2" data-v-477548e5></rect><rect class="rf-ear" x="54.4" y="26" width="4.6" height="12" rx="2.2" data-v-477548e5></rect><rect class="rf-head" x="10" y="12" width="44" height="32" rx="13" data-v-477548e5></rect><rect class="rf-screen" x="15" y="18" width="34" height="20" rx="8" data-v-477548e5></rect>',6)),e("g",we,[c.mood==="happy"?(s(),a($,{key:0},[i[0]||(i[0]=e("path",{class:"rf-eye",d:"M21 27.6 Q25 22.9 29 27.6"},null,-1)),i[1]||(i[1]=e("path",{class:"rf-eye",d:"M35 27.6 Q39 22.9 43 27.6"},null,-1))],64)):(s(),a($,{key:1},[e("circle",{class:"rf-eye",cx:"25",cy:c.mood==="think"?25.6:27.2,r:c.mood==="concern"?2.9:3.4},null,8,$e),e("circle",{class:"rf-eye",cx:"39",cy:c.mood==="think"?25.6:27.2,r:c.mood==="concern"?2.9:3.4},null,8,Se)],64))]),c.mood==="happy"?(s(),a("path",Ce)):c.mood==="concern"?(s(),a("path",Le)):c.mood==="think"?(s(),a("circle",Ae)):(s(),a("path",qe)),i[3]||(i[3]=e("rect",{class:"rf-body",x:"19",y:"45.5",width:"26",height:"11",rx:"5"},null,-1)),i[4]||(i[4]=e("circle",{class:"rf-chest",cx:"32",cy:"51",r:"2.4"},null,-1))],6))}},W=G(Ee,[["__scopeId","data-v-477548e5"]]),U=[{id:"compose",ch:"01 结构",path:"/",q:"锂离子电池由哪几部分组成？",a:'四个基本部分：正极、负极、电解液、隔膜。正负极是锂离子的"家"，电解液是锂离子迁移的"水路"，隔膜把两侧隔开、只让离子通过而挡住电子——所以电子只能走外电路。',kw:["组成","结构","正极","负极","电解液","隔膜","部分","构成"]},{id:"bs01",ch:"01 结构",path:"/",q:"BS-01 是什么？是真电池吗？",a:"BS-01 是本作品按 26650（Φ26×65 mm，5000 mAh / 3.6 V / NMC）真实标称规格构建的**概念标本**，只用于三维演示，不是实验室里的实体电池，也不是某个在售型号。真实实测数据来自 NASA PCoE 数据集的四颗 18650，两者不混用。",kw:["BS-01","概念标本","26650","21700","规格","真电池","演示"]},{id:"demo-vs-real",ch:"01 结构",path:"/",q:"页面上的演示数值和实测数据怎么区分？",a:'看常驻口径标签：带"实测"徽标的数据直接来自 NASA PCoE 数据集记录；标"示意 / 概念 / 定性"的图是编者依据公开资料人工设定、只用于呈现趋势。本作品的原则是：要么实测，要么在页面上当场声明是示意。',kw:["演示数值","实测","示意","区别","区分","口径","数据来源"]},{id:"package",ch:"02 结构",path:"/types",q:"圆柱、方形、软包三种封装有什么区别？",a:'圆柱（如 18650 / 21700）卷芯对称、强度高、成组留有间隙；方形铝壳空间利用率高；软包用铝塑膜、重量最轻但需要刚性约束。外形封装只说"长什么样"，不决定化学体系——这是两个独立的分类维度。',kw:["圆柱","方形","软包","封装","区别","18650","21700","外形"]},{id:"jellyroll",ch:"02 结构",path:"/types",q:"卷芯的叠层顺序是什么？隔膜有什么用？",a:"卷芯按正极—隔膜—负极—隔膜的顺序卷绕。隔膜是电子绝缘体，物理上隔开正负极防止短路，同时微孔让锂离子通过；一旦隔膜被刺穿（例如枝晶刺穿），就会形成内短路。",kw:["卷芯","叠层","顺序","隔膜","作用","短路"]},{id:"electron-path",ch:"03 原理",path:"/principle",q:"放电时电子往哪走？",a:'放电时负极失去电子，电子经**外电路**流向正极，与回到正极的 Li⁺ 结合。电池内部只有离子在迁移，电子不走内部——电解液和隔膜都是电子绝缘体。中文网有些动画把电子画成"穿过隔膜"，那是错的。',kw:["电子","流向","外电路","放电","正极","负极","隔膜","错误"]},{id:"ion-path",ch:"03 原理",path:"/principle",q:"充电时锂离子怎么走？",a:'充电时锂离子从正极脱出，经过电解液、穿过隔膜的微孔，嵌入负极；同时电子经外电路流向负极，与锂离子在负极表面会合。像上下班：离子走"内部通道"，电子走"外部高速路"。',kw:["锂离子","路径","充电","嵌入","脱出","怎么走","Li+"]},{id:"rate-polarization",ch:"03 原理",path:"/principle",q:"为什么充放电倍率越高，可放出的容量通常越低？",a:'大倍率下电极内部锂浓度梯度与极化增大，部分活性材料来不及参与反应，端电压提前到达截止值，容量就"看起来"变少了。电池本身的额定容量并没有改变——变的是能用上的部分。',kw:["倍率","极化","容量","为什么","越高","越低","快充","C数"]},{id:"cccv",ch:"03 原理",path:"/principle",q:"CC-CV 充电为什么要有恒压段？",a:"恒流段（CC）快速把电量充到大部分；越接近满电，锂离子嵌入越困难，电流自然衰减。恒压段（CV）把电压稳住、让电流继续降到很小，既能把电充得更满，又避免过充。本作品 BS-01 概念设定下 1C = 5.0 A，CV 段终止电流约 0.05C（250 mA）。",kw:["CC-CV","恒流","恒压","两段","充电","为什么","1C","5.0A"]},{id:"cell-code",ch:"02 结构",path:"/types",q:"21700 / 18650 这些数字是什么意思？",a:'圆柱电芯型号用"直径 + 高度"表示：21 = 直径 21 mm，700 = 高度 70.0 mm；18650 即直径 18 mm、高 65.0 mm。它们**不是**容量，也不是电压。',kw:["21700","18650","型号","直径","高度","意思","规格"]},{id:"aging-overview",ch:"04 老化",path:"/aging",q:"电池老化都有哪些机制？",a:"本作品第 04 章把老化归为六类：SEI 膜增厚、析锂（锂沉积）、颗粒开裂、材料失活（LAM）、电解液减少、产气鼓胀。它们不是某一天突然发生，而是在一次次循环里共同累积——容量慢慢降、内阻慢慢涨。",kw:["老化","机制","哪些","六类","原因","衰减"]},{id:"sei",ch:"04 老化",path:"/aging",q:"SEI 膜是什么？为什么会一直变厚？",a:'SEI（固体电解质界面膜）是首次充电时电解液在负极表面分解形成的一层保护膜。它受扩散限制：膜越厚，离子穿过越慢，生长速率越慢（dL/dt ∝ 1/L，积分得 L ∝ √t）。所以老化通常表现为早期衰减较快、后段逐渐趋缓。代价是：每长厚一点，就永久"锁住"一点可循环的锂，容量缓慢下降。',kw:["SEI","界面膜","增厚","变厚","为什么","早期","趋缓","保护膜"]},{id:"plating",ch:"04 老化",path:"/aging",q:"析锂是什么？为什么会发生？",a:"本该嵌入负极的锂，来不及进去，就在表面堆成银白色金属锂（针状枝晶或苔状沉积）。根因是**速率竞争**：低温充电、大倍率快充时，锂离子到达界面的速率超过固相扩散速率，表面锂浓度累积、局部电位降到锂沉积平衡电位以下。后果有两个：析出的锂失去活性造成容量损失；枝晶可能刺穿隔膜造成内短路。",kw:["析锂","枝晶","快充","低温","为什么","银白色","沉积","内短路"]},{id:"crack",ch:"04 老化",path:"/aging",q:"颗粒为什么会开裂？",a:'嵌锂 / 脱锂使晶格体积反复变化，颗粒像在"呼吸"，内部应力循环累积导致疲劳开裂。深充深放（大放电深度）和高倍率会加速。裂纹暴露新表面、生成更多 SEI，严重时颗粒碎裂、失去电接触。',kw:["开裂","裂纹","颗粒","应力","呼吸","疲劳","深充深放"]},{id:"lam",ch:"04 老化",path:"/aging",q:"什么是材料失活（LAM）？",a:'一部分电极颗粒"掉队"了——因为开裂、导电网络破坏或粘结剂失效，与电极失去电子连接，不再参与充放电。表现为部分颗粒从活性色变成灰色，容量台阶式下降且不可逆。',kw:["LAM","失活","材料损失","掉队","灰色","颗粒","不参与"]},{id:"lli",ch:"04 老化",path:"/aging",q:"LLI 和 LAM 有什么区别？",a:'LLI（锂库存损失）是"搬运工的锂变少了"——被 SEI 或析出的死锂锁住；LAM（活性材料损失）是"干活的房子变少了"——颗粒失活或破碎。两者都让容量下降，但成因和补救思路不同。',kw:["LLI","LAM","区别","锂库存","容量损失"]},{id:"electrolyte-loss",ch:"04 老化",path:"/aging",q:"电解液减少会怎样？",a:'电解液参与 SEI 生长等副反应被持续消耗，浸润性变差，锂离子的"水路"变窄——离子传输阻力变大，内阻上升，倍率性能下降。高温储存和长期循环都会加速消耗。',kw:["电解液","减少","消耗","内阻","倍率","高温"]},{id:"gas",ch:"04 老化",path:"/aging",q:"电池为什么会鼓胀？",a:"副反应产生气体（H₂、CO₂、烷烃等）在电芯内积聚，自由体积被挤占、内压升高，外壳就鼓起来了。过充、高温、析锂后的副反应都会加剧产气。鼓胀让界面接触变差，严重时是热失控的前兆信号之一。",kw:["鼓胀","鼓包","产气","气体","胀","变形","内压"]},{id:"resistance",ch:"04 老化",path:"/aging",q:"老化的两种表现是什么？",a:"容量下降（能装的水变少）和内阻增长（水流起来更费劲）。容量损失主要来自 LLI 与 LAM；内阻增长与电解液消耗、界面退化、接触失效都有关。两者往往同时发生，但变化幅度并不同步。",kw:["内阻","容量","表现","两种","增长","下降"]},{id:"soh",ch:"05 数据",path:"/datalab",q:"SOH 是什么？怎么算？",a:"SOH（健康状态）最常用的口径是容量比：当前可用放电容量 ÷ 初始额定容量。本作品第 05、07 章均采用这一口径；工程上也常用 80% 作为寿命终止的教学参考线（对应 NASA 数据集中约 1.4 Ah）。",kw:["SOH","健康状态","定义","计算","容量比","80%"]},{id:"nasa",ch:"05 数据",path:"/datalab",q:"本站的实测数据是哪里来的？",a:"NASA Ames 研究中心 PCoE 公开电池数据集：四颗 18650（B0005 / B0006 / B0007 / B0018，额定 2.0 Ah），24 ℃ 下以 1.5 A 恒流充至 4.2 V 转恒压至 20 mA，再以 2.0 A 放电至各自截止电压，逐循环记录放电容量。第 05 章的容量曲线逐点直取该数据集，未做拟合或平滑。",kw:["NASA","数据集","实测","来源","PCoE","18650","B0005","怎么测"]},{id:"usage-factors",ch:"05 数据",path:"/datalab",q:"哪些使用习惯最影响电池寿命？",a:"三个维度：温度（高温加速副反应与 SEI 生长，低温快充容易析锂）、倍率（大倍率极化与发热更大）、放电深度（深充深放加剧应力与材料疲劳）。可以到第 05 章的环境趋势矩阵里逐项点着看。",kw:["寿命","习惯","温度","倍率","放电深度","影响","快充","怎么用"]},{id:"eol",ch:"05 数据",path:"/datalab",q:"EOL 是什么判据？",a:'EOL（寿命终止）指电池被认为"用到头了"的状态。本作品采用 SOH 80%（约 1.4 Ah）作为**教学参考线**——这是业界常用口径之一，并非数据集自带的唯一判据。',kw:["EOL","寿命终止","判据","80%","1.4Ah","报废"]},{id:"methods",ch:"06 模型",path:"/prediction",q:"寿命预测有哪些方法路线？",a:"三类：物理模型（讲机理，可解释但建模重）、数据驱动（从历史数据抓规律，需要数据量与质量）、融合方法（用物理约束补数据驱动的短，取两者之长）。它们不是谁取代谁，而是适用边界不同。",kw:["预测","方法","物理模型","数据驱动","融合","路线","PINN"]},{id:"interpretable",ch:"06 模型",path:"/prediction",q:"可解释性在寿命预测里有什么用？",a:'一个只说"还剩 200 循环"的黑箱结论，无法回答"为什么"。可解释的模型能指出退化主要来自哪种机制、对哪些工况敏感，工程上才知道该怎么改使用策略。判断可信度也要看它：给不给不确定度、有没有经过回测检验。',kw:["可解释","黑箱","为什么","价值","可信"]},{id:"holdout",ch:"07 预测",path:"/ending",q:"什么是留出法回测？为什么能检验预测？",a:'把后续一段真实数据留出来、不参与拟合，再拿模型对它做预测，与真实值比对。用训练数据自证是"背下了答案"；只有预测模型没见过的未来，才能检验它是不是真的会外推。',kw:["留出法","回测","检验","外推","为什么","holdout","拟合"]},{id:"theil-sen",ch:"07 预测",path:"/ending",q:"退化率是怎么估出来的？",a:"第 07 章用 Theil–Sen 中位斜率估计：取所有点对斜率的中位数作为趋势。电池容量序列存在恢复尖峰与测量波动，最小二乘会被这些点带偏，中位斜率不会。之后用单调指数基线外推，预测区间由历史拟合残差传播得到、随预测距离展宽。",kw:["Theil","Sen","退化率","估计","中位","斜率","外推","怎么算"]},{id:"rul",ch:"07 预测",path:"/ending",q:"RUL 和 EOL 是什么关系？",a:"EOL 是寿命终止的那个点；RUL（剩余使用寿命）是**从当前时刻到 EOL 还有多少循环**。RUL 的单位是循环数，不是百分比；EOL 也不是厂商出厂设定的固定值，它与使用方式密切相关。",kw:["RUL","EOL","剩余寿命","关系","循环","单位"]},{id:"interval",ch:"07 预测",path:"/ending",q:"预测区间和置信区间是一回事吗？",a:'不是。本作品给出的是**基线输出**：用历史拟合残差传播构造的区间，随预测距离展宽，表达"模型对这段外推有多不确定"。它不等同于严格的统计置信区间，也不等同于 PINN 类方法给出的物理置信度——页面常驻声明了这一点。',kw:["预测区间","置信区间","区别","不确定","区间"]},{id:"holdout-numbers",ch:"07 预测",path:"/ending",q:"留出法回测的结果数字是多少？",a:"以 B0005 前 80 次真实记录拟合：预测 EOL 约在第 97 循环、RUL 约 17 循环；实际第 101 循环触及 1.4 Ah 参考线，误差约 4 循环，区间 89—106 覆盖了实测值。这些数字由页面同一套基线现算，动画与面板共用同一数据文件，不会对不上。",kw:["97","101","17","回测","结果","数字","误差","B0005"]},{id:"how-to-learn",ch:"08 学习",path:"/learn",q:"这个网站应该怎么学？",a:"推荐两条路：按 01 → 07 顺序走完七章（课后自学），或只挑感兴趣的章节单点进入（课堂演示 / 开放日）。每章页尾有本章学习目标，第 08 章有自测题和两个小游戏。全部走完约需 20—30 分钟。",kw:["怎么学","学习路径","顺序","入门","新手","多久"]},{id:"games",ch:"08 学习",path:"/learn",q:"第 08 章的小游戏怎么玩？",a:"「电芯小医生」：看症状选主凶机制，五轮诊断，答错我会讲懂为什么；「快充抉择」：每一轮给下一段使用选充电策略，SOH 曲线随选择实时变化，看谁能把电池用得最久。两个游戏都是**概念模拟**，用来理解机制之间的关系，不是真实电化学仿真。",kw:["小游戏","玩","电芯小医生","快充抉择","规则","趣味"]},{id:"robot-intro",ch:"08 学习",path:"/learn",q:"你是谁？能回答什么？",a:"我是小锂，这个作品的站内学习助手。我学过本站七章的全部内容——结构、原理、老化机制、实测数据、预测方法。答错题或游戏失误时我会主动出来讲解；你也可以随时问我。我的回答来自站内知识库检索，涉及实测数据的结论请以第 05 / 07 章页面为准。",kw:["你是谁","小锂","助手","能做什么","机器人","范围"]},{id:"data-source-summary",ch:"08 学习",path:"/learn",q:"哪些内容是真实的，哪些是示意？",a:"真实实测：第 05 章的逐循环容量曲线、第 07 章的回测（均来自 NASA PCoE 数据集，逐点直取或明确推导）。示意 / 概念：老化进程动画、化学体系雷达、方法权衡散点、以及所有小游戏的数值——页面对这些都带常驻口径声明。技术路径与素材台账不在站内展示，写在参赛介绍文档里。",kw:["真实","示意","哪些","数据真实性","台账","来源"]}],Ie={鼓胀:["产气","鼓包","胀气","变形","胖"],SOH:["健康状态","容量比","衰减","健康度"],RUL:["剩余寿命","还能用多久","还剩"],EOL:["寿命终止","报废","寿命终点","到头"],倍率:["C数","快充","快慢","倍率性能"],"CC-CV":["恒流恒压","两段式","充电制度"],枝晶:["析锂","针状","银白"],SEI:["界面膜","钝化膜","膜"],留出法:["回测","检验","验证"],内阻:["阻力","内阻增长"],隔膜:["隔离膜"],NASA:["数据集","实测数据","来源"],快充:["倍率","大电流"],低温:["冬天","寒冷"],容量:["电量","能装多少"]},Be=()=>!1,Me=()=>U.length;function K(c)